CREATE TEMPORARY VIEW user_exp_mapping_${grass_region_without_quote} AS
SELECT
    user_id
    ,exp_group_id
    ,experiment_id
FROM
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND is_assignment_log = 1
    AND experiment_id IN (11548, 23605, 18853, 197181, 200522, 202945);

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_session_${grass_region_without_quote} AS 
SELECT
    search_session_id
    ,MAX(shop_recall_type) AS shop_recall_type
    ,MAX(IF(operation = 'impression', is_ads, NULL)) AS shop_is_ads
    ,MAX(IF(operation = 'impression', true, false)) AS with_shop_card
FROM 
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_section IS NULL 
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND (
        operation = 'view'
        OR (
            target_type IN ('shop','shop_item','shop_livestream','shop_banner','shop_voucher')
            AND operation = 'impression'
        )
    )
    AND search_session_id != ''
GROUP BY 
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_session_cube_${grass_region_without_quote} AS 
SELECT
    search_session_id
    ,IF(shop_is_ads = true, 'ads', 'org') AS shop_card_type
FROM 
    dws_session_${grass_region_without_quote}
WHERE 
    shop_is_ads IS NOT NULL
UNION ALL 
SELECT
    search_session_id
    ,IF(shop_recall_type IN ('4','401','5','501'), 'shop_ads', 'brand_ads') AS shop_card_type
FROM 
    dws_session_${grass_region_without_quote}
WHERE 
    shop_is_ads = true
    AND (shop_recall_type IN ('4','401','5','501') OR shop_recall_type LIKE '12%')
UNION ALL
SELECT
    search_session_id
    ,IF(with_shop_card = true, 'all_shop_cards', 'non_shop_card') AS shop_card_type
FROM 
    dws_session_${grass_region_without_quote}
UNION ALL
SELECT
    search_session_id
    ,'__ALL__' AS shop_card_type
FROM 
    dws_session_${grass_region_without_quote};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_omni_order_${grass_region_without_quote} AS
SELECT
    CASE
        WHEN 
            target_type IN ('item', 'video', 'livestream', 'shop','shop_item','shop_livestream','shop_banner','shop_voucher')
            AND page_section IS NULL
            AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
            THEN search_session_id
        WHEN
            source1_target_type IN ('item', 'video', 'livestream', 'shop','shop_item','shop_livestream','shop_banner','shop_voucher')
            AND source1_page_section IS NULL
            AND source1_page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
            THEN source1_search_session_id
        WHEN
            source2_target_type IN ('item', 'video', 'livestream', 'shop','shop_item','shop_livestream','shop_banner','shop_voucher')
            AND source2_page_section IS NULL
            AND source2_page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
            THEN source2_search_session_id
    END AS search_session_id
    ,user_id
    ,CASE
        WHEN (page_type IN ('global_search', 'search_in_pdp', 'search_prefill') AND page_section IS NULL AND target_type IN ('item', 'video', 'livestream'))
            OR (source1_page_type IN ('global_search', 'search_in_pdp', 'search_prefill') AND source1_page_section IS NULL AND source1_target_type IN ('item', 'video', 'livestream'))
            OR (source2_page_type IN ('global_search', 'search_in_pdp', 'search_prefill') AND source2_page_section IS NULL AND source2_target_type IN ('item', 'video', 'livestream')) 
        THEN 'main_cards'
        ELSE 'shop_cards'
    END AS card_type
    ,SUM(IF(operation = 'impression', operation_cnt, NULL)) AS imp_cnt
    ,SUM(IF(operation = 'click', operation_cnt, NULL)) AS click_cnt
    ,SUM(IF(operation = 'order', operation_cnt, NULL)) AS order_cnt
    ,SUM(IF(operation = 'order', place_order_gmv, NULL)) AS gmv
FROM 
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND ((
        operation IN ('impression')
        AND target_type IN ('item', 'video', 'livestream', 'shop')
        AND page_section IS NULL
        AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    ) OR (
        operation IN ('click', 'order')
        AND target_type IN ('item', 'video', 'livestream', 'shop','shop_item','shop_livestream','shop_banner','shop_voucher')
        AND page_section IS NULL
        AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    ) OR (
        operation IN ('order')
        AND source1_target_type IN ('item', 'video', 'livestream', 'shop','shop_item','shop_livestream','shop_banner','shop_voucher')
        AND source1_page_section IS NULL
        AND source1_page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    ) OR (
        operation IN ('order')
        AND source2_target_type IN ('item', 'video', 'livestream', 'shop','shop_item','shop_livestream','shop_banner','shop_voucher')
        AND source2_page_section IS NULL
        AND source2_page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    ))
GROUP BY 
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_omni_order_res_${grass_region_without_quote} AS
SELECT
    user_id
    ,IF(card_type IS NOT NULL, card_type, '__ALL__' ) AS card_type
    ,IF(shop_card_type IS NOT NULL, shop_card_type, '__ALL__') AS shop_card_type
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
FROM 
    dws_omni_order_${grass_region_without_quote} a
LEFT JOIN
    dws_session_cube_${grass_region_without_quote} b 
ON
    a.search_session_id = b.search_session_id
GROUP BY GROUPING SETS (
    (user_id, card_type, shop_card_type)
    ,(user_id, shop_card_type)
);

--sql_divide_splitter--

CREATE TEMPORARY VIEW omni_exp_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,card_type
    ,shop_card_type
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,COUNT(DISTINCT (IF(imp_cnt > 0, a.user_id, NULL))) AS imp_uu
    ,COUNT(DISTINCT (IF(click_cnt > 0, a.user_id, NULL))) AS click_uu
    ,COUNT(DISTINCT (IF(order_cnt > 0, a.user_id, NULL))) AS order_uu
FROM
    dws_omni_order_res_${grass_region_without_quote} a
INNER JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id 
GROUP BY 
    1,2,3,4;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_ads_${grass_region_without_quote} AS
SELECT
    *
FROM (
    SELECT 
        ads_id
        ,placement
        ,sub_product_type
        ,product_type
        ,main_product_type
        ,ROW_NUMBER() OVER (PARTITION BY ads_id  ORDER BY placement DESC) AS rank
    FROM
        mp_paidads.dim_advertise__reg_s0_live
    WHERE
        grass_region = ${grass_region}
        AND grass_date = ${local_date}
        AND tz_type = 'local'
)  
WHERE
    rank = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_search_req_item_${grass_region_without_quote} AS
SELECT
    item_id 
    ,request_id
    ,MAX(search_session_id) AS search_session_id
FROM 
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND operation = 'impression'
    AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
    AND page_section IS NULL
    AND target_type IN ('item', 'video', 'livestream')
GROUP BY 
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_ads_performance_${grass_region_without_quote} AS
SELECT
    user_id
    ,'shop_cards' AS card_type
    ,CASE
        WHEN GROUPING(main_product_type) = 1 THEN '__ALL__'
        WHEN main_product_type = 'Shop Ads' THEN 'shop_ads'
        WHEN main_product_type = 'Brand Ads' THEN 'brand_ads'
    END AS shop_card_type
    ,SUM(a.expenditure_amt_usd) as ads_rev
FROM 
    mp_paidads.dwd_advertise_performance_di__reg_s0_live a
INNER JOIN
    dim_ads_${grass_region_without_quote} b 
ON
    a.ads_id = b.ads_id
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND user_id > 0
    AND entrance = 5
    AND tz_type = 'local'
    AND main_product_type IN ('Shop Ads', 'Brand Ads')
GROUP BY GROUPING SETS
    ((user_id, 'shop_cards', main_product_type), (user_id, 'shop_cards'))
UNION ALL
SELECT
    user_id
    ,'main_cards' AS card_type
    ,COALESCE(shop_card_type, '__ALL__') AS shop_card_type
    ,SUM(a.expenditure_amt_usd) as ads_rev
FROM 
    mp_paidads.dwd_advertise_performance_di__reg_s0_live a
    LEFT JOIN dws_search_req_item_${grass_region_without_quote} b 
    ON a.request_id = b.request_id
        AND a.item_id = b.item_id 
    LEFT JOIN dws_session_cube_${grass_region_without_quote} c
    ON b.search_session_id = c.search_session_id 
WHERE
    grass_region = ${grass_region}
    AND grass_date = ${local_date}
    AND user_id > 0
    AND entrance = 1
    AND tz_type = 'local'
GROUP BY 
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_ads_performance_broadcast_${grass_region_without_quote} AS
SELECT
    user_id
    ,card_type
    ,shop_card_type
    ,ads_rev
FROM
    dws_ads_performance_${grass_region_without_quote}
UNION ALL
SELECT
-- Broadcast ads_rev from __ALL__ into ads & all_shop_cards for shop_cards
    user_id
    ,a.card_type AS card_type
    ,b.shop_card_type AS shop_card_type
    ,ads_rev
FROM
    dws_ads_performance_${grass_region_without_quote} a
LATERAL VIEW
    EXPLODE(ARRAY('ads', 'all_shop_cards')) b AS shop_card_type
WHERE
    a.card_type = 'shop_cards'
    AND a.shop_card_type = '__ALL__';

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_ads_res_${grass_region_without_quote} AS
SELECT
    user_id
    ,COALESCE(card_type, '__ALL__') AS card_type
    ,shop_card_type
    ,SUM(ads_rev) AS ads_rev
FROM 
    dws_ads_performance_broadcast_${grass_region_without_quote}
GROUP BY GROUPING SETS 
(
    (user_id, card_type, shop_card_type), (user_id, shop_card_type)
);

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_ads_exp_${grass_region_without_quote} AS
SELECT
    experiment_id
    ,exp_group_id
    ,card_type
    ,shop_card_type
    ,SUM(ads_rev) AS ads_rev
FROM
    dws_ads_res_${grass_region_without_quote} a
INNER JOIN
    user_exp_mapping_${grass_region_without_quote} b
ON
    a.user_id = b.user_id 
GROUP BY 
    1,2,3,4;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_srp_shop_recall_metrics_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    COALESCE(a.experiment_id, b.experiment_id) AS experiment_id
    ,COALESCE(a.exp_group_id, b.exp_group_id) AS exp_group_id
    ,COALESCE(a.shop_card_type, b.shop_card_type) AS shop_card_type
    ,COALESCE(a.card_type, b.card_type) AS card_type
    
    ,order_cnt
    ,order_uu
    ,gmv
    ,ads_rev
    ,imp_cnt
    ,imp_uu
    ,click_cnt
    ,click_uu
FROM
    dws_ads_exp_${grass_region_without_quote} a 
FULL OUTER JOIN
    omni_exp_${grass_region_without_quote} b 
ON
    a.experiment_id = b.experiment_id
    AND a.exp_group_id = b.exp_group_id
    AND a.shop_card_type = b.shop_card_type
    AND a.card_type = b.card_type;
